export const getSetCompletionUrl = (id: number,) => {




  return `/api/habits/${id}/completion`
}

export const setCompletion = async (id: number,
    completionInput: CompletionInput, options?: Parameters<typeof customFetch>[1]): Promise<Habit> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<Habit>(getSetCompletionUrl(id),
  {
    ...options,
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(completionInput)
  }
);}





export const getSetCompletionMutationKey = () => ['setCompletion'] as const;

export const getSetCompletionMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof setCompletion>>, TError,SetCompletionMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof setCompletion>>, TError,SetCompletionMutationVariables, TContext> => {

const mutationKey = getSetCompletionMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof setCompletion>>, SetCompletionMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  setCompletion(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type SetCompletionMutationResult = NonNullable<Awaited<ReturnType<typeof setCompletion>>>
    export type SetCompletionMutationBody = BodyType<CompletionInput>
    export type SetCompletionMutationError = ErrorType<unknown>
    export type SetCompletionMutationVariables = {id: number;data: BodyType<CompletionInput>}

    export const useSetCompletion = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof setCompletion>>, TError,SetCompletionMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof setCompletion>>,
        TError,
        SetCompletionMutationVariables,
        TContext
      > => {
      return useMutation(getSetCompletionMutationOptions(options), queryClient);
    }

